SELECT CASE WHEN (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'provisoes_folha' AND policyname IN ('provisoes_folha_insert','provisoes_folha_update','provisoes_folha_delete')) = 3 AND EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'historico_calculos_folha' AND policyname = 'historico_calculos_delete') THEN 'ok' ELSE 'FALHOU: write policies de provisoes_folha/historico_calculos_folha ausentes' END;
